# Login - Retry To Success

```
import { Login } from 'story-parity-research';
import { fn } from 'storybook/test';

const RetryToSuccess = () => <Login
    heading="Sign in"
    authenticate={fn(async(email:string,password:string)=>{
      await new Promise(resolve=>setTimeout(resolve,30));
      if(password!=='correct-horse')throw new Error('Invalid credentials.');
      return {email};
    })} />;
```
